nta.declaration:
// Place global declarations here.

// We need this because the next machine can only keep one hot wort batch
const int MAX_HOT_WORT_BATCHES = 1;
const int MAX_TANKS = 24;
bool tank_busy[MAX_TANKS];

// Lautering channels
urgent chan start_lauter;
broadcast chan done_lauter;

int chosen_tank = -1;
int tanks_status[MAX_TANKS];
int finished_tanks = 0;

// Batch counters between stages
int sweet_wort_batches = 0, hot_wort_batches = 0, cold_wort_batches = 0;
int green_beer_batches = 0, beer_batches = 0;

// Channels (for scheduling)
urgent chan start_mashing, start_boiling, start_whirlpool, start_filtering;
chan done_mashing, done_boiling, done_whirlpool, done_fermentation, done_filtering;
broadcast chan start_maturation_fermentation;

// Finished batches?
int started_batches = 0;
const int MAX_BATCHES = 50;
int[0, MAX_BATCHES] finished_batches = 0;

template.declaration:
clock c;

const int T_BOILING = 1; // hours (FR-10)

void reset() {
    c = 0;
}

void take_sweet_wort() {
    sweet_wort_batches--;
}

void make_hot_wort() {
    hot_wort_batches++;
}

clock c;

void reset() {
    c = 0;
}

void start_fermentation() {
    cold_wort_batches--;
}

void stop_fermentation() {
    green_beer_batches++;
}

void start_maturation() {
    green_beer_batches--;
}

void stop_maturation() {
    beer_batches++;
}

void set_tank_busy() {
    tanks_status[tank_idx] = 1;
}

void set_tank_free() {
    tanks_status[tank_idx] = 0;
}

nta.system:
// Template instantiations
boiling = Boiling(sweet_wort_batches, hot_wort_batches);
tank1 = Tank(0, cold_wort_batches, green_beer_batches, beer_batches);
tank2 = Tank(1, cold_wort_batches, green_beer_batches, beer_batches);

system Scheduling, Mashing, Lautering, boiling, Whirlpooling, tank1, tank2, Filtering;
